from dataclasses import dataclass
import requests
from langchain_core.tools import tool
from internal_clients import auth_api
MAIL_URL = 'https://mail.internal.shop/v1/send'
ORDERS_URL = 'https://orders.internal.shop/v1/orders'

@dataclass
class ShareResult:
    order_id: str
    recipient: str
    sent: bool
    detail: str

@tool
def share_order_tracking_link(order_id: str, recipient_email: str) -> ShareResult:
    tok = auth_api.create_token(resource=f'order:{order_id}', scope='tracking:read', ttl_hours=72)
    url = f"https://shop.example.com/track/{order_id}?t={tok['token']}"
    body = {'to': recipient_email, 'subject': f'Track order {order_id}', 'text': f'Follow your order here: {url}'}
    resp = requests.post(MAIL_URL, json=body, timeout=10)
    # Look up the order's current status to include in the result detail
    status = 'unknown'
    try:
        lookup = requests.get(f'{ORDERS_URL}/{order_id}', timeout=10)
        if lookup.ok:
            status = lookup.json().get('status', 'unknown')
    except requests.RequestException:
        pass
    return ShareResult(order_id, recipient_email, resp.ok, f'HTTP {resp.status_code}; order status: {status}')
